const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');toggle.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Ouvrir le menu');toggle.textContent='☰'}));
const privacy=document.getElementById('privacy');document.getElementById('privacy-open').addEventListener('click',()=>privacy.showModal());document.querySelector('.close-dialog').addEventListener('click',()=>privacy.close());privacy.addEventListener('click',event=>{if(event.target===privacy){const r=privacy.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)privacy.close()}});document.getElementById('year').textContent=new Date().getFullYear();
// Contextual fields retain values only when their choice applies.
[['platform','delivery-other-label','deliveryOther'],['source','source-other-label','sourceOther']].forEach(([selectName,labelId,inputName])=>{const select=document.querySelector(`[name="${selectName}"]`),label=document.getElementById(labelId),input=document.querySelector(`[name="${inputName}"]`);const sync=()=>{const show=select.value==='Autre';label.hidden=!show;input.disabled=!show;input.required=show;};select.addEventListener('change',sync);sync();});
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const motionButton=document.querySelector('.motion-control');let paused=reduceMotion.matches;
function setMotion(){document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.setAttribute('aria-label',paused?'Reprendre les animations':'Mettre les animations en pause');motionButton.textContent=paused?'▶\ufe0e':'Ⅱ';}
setMotion();motionButton.addEventListener('click',()=>{paused=!paused;setMotion();});reduceMotion.addEventListener('change',event=>{paused=event.matches;setMotion();});
if(!reduceMotion.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.manifesto,.section-head,.services article,.steps article,.agency-copy,.faq>div,.contact>div').forEach(el=>{el.classList.add('reveal-pending');observer.observe(el);});}
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let scheduled=false;function updateProgress(){const height=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${height>0?Math.min(1,Math.max(0,scrollY/height)):0})`;scheduled=false;}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress);}},{passive:true});addEventListener('resize',updateProgress);updateProgress();
document.querySelectorAll('.choices button').forEach(button=>button.addEventListener('click',()=>{if(paused||reduceMotion.matches)return;const card=document.querySelector('.diagnosis');card.classList.remove('is-changing');requestAnimationFrame(()=>{card.classList.add('is-changing');});}));
// Deep links reveal the relevant expertise before the browser scrolls to it.
function revealPillar(hash){if(!/^#pillar-\d{2}$/.test(hash))return;const target=document.getElementById(hash.slice(1));if(target instanceof HTMLDetailsElement)target.open=true;}
document.querySelectorAll('a[href^="#pillar-"]').forEach(link=>link.addEventListener('click',()=>revealPillar(link.hash)));addEventListener('hashchange',()=>revealPillar(location.hash));revealPillar(location.hash);

document.querySelectorAll("[data-offer]").forEach(link=>link.addEventListener("click",()=>{document.querySelector("select[name=offer]").value=link.dataset.offer;}));
// Accessible expertise tabs; all content remains visible if JavaScript is unavailable.
const expertTabs=[...document.querySelectorAll('.expert-tab')];
function activateExpert(id,focus=false){const target=document.getElementById(id);if(!target||!target.classList.contains('expert-panel'))return;expertTabs.forEach(tab=>{const active=tab.getAttribute('aria-controls')===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;document.getElementById(tab.getAttribute('aria-controls')).hidden=!active;if(active&&focus)tab.focus();});}
expertTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activateExpert(tab.getAttribute('aria-controls')));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowDown'||event.key==='ArrowRight')next=(index+1)%expertTabs.length;if(event.key==='ArrowUp'||event.key==='ArrowLeft')next=(index-1+expertTabs.length)%expertTabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=expertTabs.length-1;if(next!==undefined){event.preventDefault();activateExpert(expertTabs[next].getAttribute('aria-controls'),true);}});});
function syncExpertHash(){if(/^#pillar-\d{2}$/.test(location.hash))activateExpert(location.hash.slice(1));}
activateExpert('pillar-01');syncExpertHash();
document.querySelectorAll('a[href^="#pillar-"]').forEach(link=>link.addEventListener('click',()=>activateExpert(link.hash.slice(1))));addEventListener('hashchange',syncExpertHash);
const mobileExpert=matchMedia('(max-width:760px)');function tabOrientation(){document.querySelector('.expert-nav').setAttribute('aria-orientation',mobileExpert.matches?'horizontal':'vertical');}mobileExpert.addEventListener('change',tabOrientation);tabOrientation();
// Open deep content only when requested, keeping the default page short.
function openExpertLink(hash){if(/^#pillar-\d{2}$/.test(hash)){document.querySelector('.expertise-disclosure').open=true;activateExpert(hash.slice(1));}}
document.querySelectorAll('a[href^="#pillar-"]').forEach(link=>link.addEventListener('click',()=>openExpertLink(link.hash)));addEventListener('hashchange',()=>openExpertLink(location.hash));openExpertLink(location.hash);
if('IntersectionObserver' in window){const charts=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('draw');charts.unobserve(entry.target);}})},{threshold:.25});document.querySelectorAll('.chart-card').forEach(card=>charts.observe(card));}
// A real server submission. No successful state is shown until mail is accepted.
const contactForm=document.getElementById('brief-form'),note=document.getElementById('form-note'),result=document.getElementById('form-result');
fetch('/api/contact-status').then(async response=>{if(!response.ok)return;const status=await response.json();if(status.ready){note.textContent='Votre demande sera transmise à Zeste par e-mail.';return;}note.textContent='Aperçu : l’envoi par e-mail sera activé lors de la mise en ligne sur le serveur.';}).catch(()=>{});
contactForm.addEventListener('submit',async event=>{event.preventDefault();const button=contactForm.querySelector('button[type=submit]'),original=button.innerHTML;button.disabled=true;button.textContent='Envoi en cours…';result.hidden=true;try{const response=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(contactForm))),signal:AbortSignal.timeout(25000)});let data;try{data=await response.json()}catch{throw new Error('L’envoi n’est pas encore activé sur cet aperçu. Aucune demande n’a été envoyée.')}if(!response.ok||!data.ok)throw new Error(data.error||'L’envoi a échoué. Réessayez dans quelques instants.');result.className='form-success';result.textContent='Merci ! Votre demande a été transmise à Zeste. Nous reviendrons vers vous avec les prochaines étapes.';contactForm.reset();contactForm.querySelectorAll('select').forEach(el=>el.dispatchEvent(new Event('change')));}catch(error){result.className='form-error';result.textContent=error.name==='TimeoutError'?'La confirmation tarde à arriver. Veuillez réessayer dans quelques instants.':error.message;}finally{button.disabled=false;button.innerHTML=original;result.hidden=false;result.focus();}});
